        "aria-label=\"Gear\""
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Icon",
      "relationship": "Buttons can contain icons alongside text or as icon-only buttons",
      "example": "<Button><Icon />Text</Button> or <Button size=\"icon\"><Icon /></Button>"
    },
    {
